/**
 * Detail panel: metadata, honest date statements, an interactive IIIF viewer
 * (region requests = real deep zoom), rights/credit and prominent links to the
 * holding institution.
 *
 * The viewer only uses documented IIIF Image API parameters (`regionByPx`,
 * `sizeByW`); every request URL is built by `iiif.js` and unit-tested there. When
 * a service refuses a region request the viewer falls back to the full-sheet
 * derivative and finally to the record thumbnail, always saying which state it is
 * in instead of showing an empty box.
 */

import { copyText, el, formatYearRange, qs, setStatus, trapFocus } from './dom.js';
import { recordCenter } from './records.js';
import {
  boundsForCanvas,
  eRaraViewerUrl,
  fullImageUrl,
  imageRequestUrl,
  panView,
  parseManifest,
  sheetThumbUrl,
  viewForCanvas,
  zoomPercent,
  zoomView,
} from './iiif.js';

const FULL_PREVIEW_WIDTH = 1000;

export function init(ctx) {
  const panel = qs('#detail');
  const body = qs('#detail-body');
  const scrim = qs('#scrim');
  if (!panel || !body) return;

  let opener = null;
  let current = null;
  let manifest = null;
  let page = 0;
  /** @type {ReturnType<typeof createViewer>|null} */
  let viewer = null;

  /** `source` records where the selection came from; the viewer behaves the same. */
  function open(record, { keepSheet = false } = {}) {
    if (!record) return;
    const changedWork = current?.id !== record.id;
    current = record;
    manifest = null;
    // A newly chosen work starts on its first sheet; an explicitly shared `sh`
    // value (deep link or reload) is kept and clamped to the real canvas count
    // once the manifest is parsed.
    if (changedWork && !keepSheet) ctx.store.update({ sheet: 1 });
    const wasOpen = !panel.hidden;
    if (!wasOpen) opener = document.activeElement;
    render(record);
    panel.hidden = false;
    if (scrim) scrim.hidden = false;
    panel.setAttribute('aria-modal', 'true');
    document.body.classList.add('has-detail');
    // Focus the heading only when the panel opens (not when its content is swapped).
    if (!wasOpen) body.querySelector('[data-detail-heading]')?.focus();
    // The viewer loads its manifest for every entry point, including `?sel=` links.
    loadManifest(record);
  }

  function close() {
    if (panel.hidden) return;
    viewer?.destroy();
    viewer = null;
    page = 0;
    // A closed panel must not leave a sheet number behind in the shared URL.
    if (ctx.store.getState().sheet !== 1) ctx.store.update({ sheet: 1 });
    panel.hidden = true;
    if (scrim) scrim.hidden = true;
    panel.setAttribute('aria-modal', 'false');
    document.body.classList.remove('has-detail');
    current = null;
    body.replaceChildren();
    opener?.focus?.();
    opener = null;

#!/usr/bin/env node
/**
 * Headless browser smoke check (development tool, not part of the build).
 *
 * Uses the Chromium binary on the runner and the DevTools protocol via Node's
 * built-in WebSocket – no npm dependencies. Collects console errors, failed
 * requests and a DOM snapshot, then writes a screenshot.
 *
 *   node scripts/browser-smoke.mjs [url] [--out /tmp/shot.png] [--wait 8000]
 */
import { spawn } from 'node:child_process';
import { writeFile, mkdtemp } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import path from 'node:path';

const url = process.argv[2]?.startsWith('http') ? process.argv[2] : 'http://127.0.0.1:8787/';
const arg = (name, fallback) => {
  const i = process.argv.indexOf(name);
  return i > -1 ? process.argv[i + 1] : fallback;
};
const out = arg('--out', '/tmp/browser-smoke.png');
const wait = Number(arg('--wait', 9000));
const port = Number(arg('--port', 9333));

const binary = ['/usr/bin/chromium', '/usr/bin/chromium-browser', '/usr/bin/google-chrome'].find(Boolean);
const userDataDir = await mkdtemp(path.join(tmpdir(), 'cdp-'));
const child = spawn(
  binary,
  [
    '--headless=new',
    `--remote-debugging-port=${port}`,
    `--user-data-dir=${userDataDir}`,
    '--no-sandbox',
    '--disable-gpu',
    '--hide-scrollbars',
    '--window-size=1440,1000',
    'about:blank',
  ],
  { stdio: ['ignore', 'ignore', 'pipe'] },
);

const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

async function endpoint(pathname) {
  for (let i = 0; i < 40; i += 1) {
    try {
      const res = await fetch(`http://127.0.0.1:${port}${pathname}`);
      if (res.ok) return res.json();
    } catch {
      /* not up yet */
    }
    await sleep(250);
  }
  throw new Error(`CDP endpoint ${pathname} not reachable`);
}

