#!/usr/bin/env node
/**
 * Degraded-state diagnostic (development tool, lives outside the repo).
 *
 * Opens the app with a set of blocked URL patterns and reports what the UI says
 * + writes a screenshot. Used to check "meaningful loading, empty and error
 * states" claims.
 *
 *   node /tmp/degraded.mjs <url> <out.png> [blockPattern ...]
 */
import { spawn } from 'node:child_process';
import { writeFile, mkdtemp } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import path from 'node:path';

const url = process.argv[2];
const out = process.argv[3];
const blocks = process.argv.slice(4);

const port = 9333 + Math.floor(Math.random() * 200);
const userDataDir = await mkdtemp(path.join(tmpdir(), 'cdp-deg-'));
const child = spawn('/usr/bin/chromium', [
  '--headless=new',
  `--remote-debugging-port=${port}`,
  `--user-data-dir=${userDataDir}`,
  '--no-sandbox',
  '--disable-gpu',
  '--hide-scrollbars',
  '--window-size=1440,1000',
  'about:blank',
], { stdio: ['ignore', 'ignore', 'pipe'] });

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
async function endpoint(pathname) {
  for (let i = 0; i < 40; i += 1) {
    try {
      const res = await fetch(`http://127.0.0.1:${port}${pathname}`);
      if (res.ok) return res.json();
    } catch { /* retry */ }
    await sleep(250);
  }
  throw new Error(`CDP ${pathname} unreachable`);
}
await endpoint('/json/version');
const target = await fetch(`http://127.0.0.1:${port}/json/new?about:blank`, { method: 'PUT' }).then((r) => r.json());
const ws = new WebSocket(target.webSocketDebuggerUrl);
await new Promise((res, rej) => { ws.onopen = res; ws.onerror = rej; });
let id = 0;
const pending = new Map();
ws.onmessage = (m) => {
  const d = JSON.parse(m.data);
  if (d.id && pending.has(d.id)) { pending.get(d.id)(d); pending.delete(d.id); }
};
const send = (method, params = {}) => new Promise((res) => {
  const mid = ++id;
  pending.set(mid, res);
  ws.send(JSON.stringify({ id: mid, method, params }));
});
const evaluate = async (expr) => {
  const r = await send('Runtime.evaluate', { expression: expr, returnByValue: true, awaitPromise: true });
  return r.result?.result?.value;
};

await send('Page.enable');
await send('Runtime.enable');
await send('Network.enable');
if (blocks.length) await send('Network.setBlockedURLs', { urls: blocks });
await send('Emulation.setDeviceMetricsOverride', { width: 1440, height: 1000, deviceScaleFactor: 1, mobile: false });
await send('Page.navigate', { url });
await sleep(Number(process.env.WAIT ?? 9000));

const state = await evaluate(`(() => ({
  notices: document.querySelector('#app-notices')?.hidden === false ? document.querySelector('#app-notices').textContent.trim().slice(0,300) : null,
  resultsState: document.querySelector('#results-state')?.hidden === false ? document.querySelector('#results-state').textContent.trim().slice(0,300) : null,
  resultsStateClass: document.querySelector('#results-state')?.className,
  resultCount: document.querySelector('#result-count')?.textContent?.trim(),
  rows: document.querySelectorAll('#result-list > *').length,
  placeStatus: document.querySelector('#place-status')?.textContent?.trim().slice(0,200),
  mapStatus: document.querySelector('#map-status')?.textContent?.trim().slice(0,200),
  detailHidden: document.querySelector('#detail')?.hidden,
  viewerState: document.querySelector('#viewer-stage')?.dataset.state,
  viewerNote: document.querySelector('#viewer-note')?.textContent?.trim().slice(0,300),
  previewImg: document.querySelector('.app-viewer__image')?.src,
  introCount: document.querySelector('#intro-count')?.textContent?.trim(),
  statsLine: document.querySelector('#stats-line, .app-stats')?.textContent?.trim().slice(0,120),
}))()`);

const shot = await send('Page.captureScreenshot', { format: 'png', captureBeyondViewport: false });
if (shot.result?.data) await writeFile(out, Buffer.from(shot.result.data, 'base64'));
console.log(JSON.stringify({ url, blocks, state, screenshot: out }, null, 1));
child.kill('SIGKILL');
ws.close();
process.exit(0);

