```js
  /** Ids of the records that pass the current filters (bus event from results.js). */
  let filteredIds = null;
  ...
  ctx.bus.on('records:filtered', ({ records }) => {
    filteredIds = new Set((records ?? []).map((r) => r.id));
    updateFilterNote();
