edits.newText:
el('h2', { class: 'app-detail__title', id: 'detail-title', 'data-detail-heading': '', tabindex: '-1', text: record.title }),
// Honest state: a shared link or a series chip can open a record the current
// filters exclude. Say so instead of letting the list and the panel disagree.
el('p', { class: 'zh-hint app-detail__filternote', id: 'detail-filter-note', hidden: true }),

  viewer = viewer_?.__viewer ?? null;
  updateFilterNote();
}

/** Name the one case where list and panel disagree by design. */
function updateFilterNote() {
  const note = qs('#detail-filter-note');
  if (!note) return;
  const outside = Boolean(current) && Boolean(filteredIds) && !filteredIds.has(current.id);
  note.hidden = !outside;
  if (outside) {
    note.textContent = 'Liegt ausserhalb der aktuellen Filter – die Ergebnisliste zeigt diesen Datensatz deshalb nicht. „Zeitraum dieses Blattes filtern“ übernimmt seine Jahre.';
  } else {
    note.textContent = '';
  }
}

ctx.bus.on('records:loaded', () => {
  const id = ctx.store.getState().selected;
  const record = ctx.data.recordIndex.get(id);
  if (id && record && panel.hidden) open(record, { keepSheet: true });
});
// Keep the “outside the current filters” note honest while the filters change.
ctx.bus.on('records:filtered', ({ records }) => {
  filteredIds = new Set((records ?? []).map((record) => record.id));
  updateFilterNote();
});

